// forProductionAt is the class that places a time on the timeline, from a closed set: the
// timeline runs 03:00 to 18:00, and only the times the page draws have a place. A time
// with none gets "", and internal/handler's test refuses a drawing that would need one.
func forProductionAt(hhmm string) string {
	switch hhmm {
	case "03:00":
		return "lp-fpAt0300"
	case "04:00":
		return "lp-fpAt0400"
	case "04:02":
		return "lp-fpAt0402"
	case "05:00":
		return "lp-fpAt0500"
	case "06:00":
		return "lp-fpAt0600"
	case "08:00":
		return "lp-fpAt0800"
	case "09:00":
		return "lp-fpAt0900"
	case "12:00":
		return "lp-fpAt1200"
	case "15:00":
		return "lp-fpAt1500"
	case "18:00":
		return "lp-fpAt1800"
	}
	return ""
}

// forProductionUntil is the class that ends a shift's bar on the timeline, from the same
// kind of closed set.
func forProductionUntil(hhmm string) string {
	switch hhmm {
	case "12:00":
		return "lp-fpTo1200"
	case "13:00":
		return "lp-fpTo1300"
	case "14:00":
		return "lp-fpTo1400"
	case "16:00":
		return "lp-fpTo1600"
	case "17:00":
		return "lp-fpTo1700"
	}
	return ""
}

